describe("Logger", () => {
  const manager = new StackContextManager();
  beforeAll(() => {
    context.setGlobalContextManager(manager);
  });
  afterAll(() => {
    context.disable();
  });

  it("filters by minSeverity and adds name and attributes", async () => {
    const { exporter, client } = setup({ minSeverity: Severity.Debug });
    const log = client.logger("orders", { region: "eu" });
    expect(log.name).toBe("orders");
    expect(log.minSeverity).toBe(Severity.Debug);
    log.trace("dropped");
    log.debug("d");
    log.info("i", { region: "us" });
    log.warn("w");
    log.error("e");
    log.fatal("f");
    await client.flush();
    expect(exporter.records.map((r) => r.severityText)).toEqual([
      "DEBUG",
      "INFO",
      "WARN",
      "ERROR",
      "FATAL",
    ]);
    expect(exporter.records[0]?.attributes).toEqual({ "logger.name": "orders", region: "eu" });
    expect(exporter.records[1]?.attributes.region).toBe("us");
    await client.close();
  });

  it("creates children and works without a name", async () => {
    const { exporter, client } = setup();
    const child = client.logger().child({ a: 1 }).child({ b: 2 });
    expect(child.name).toBeUndefined();
    expect(child.isEnabled(Severity.Debug)).toBe(false);
    child.info("c");
    const named = new Logger(client, { name: "n" }).child({ c: 3 });
    expect(named.name).toBe("n");
    named.warn("n");
    await client.flush();
    expect(exporter.records[0]?.attributes).toEqual({ a: 1, b: 2 });
    expect(exporter.records[1]?.attributes).toEqual({ "logger.name": "n", c: 3 });
    await client.close();
  });

  it("correlates with the active span", () => {
    const sent: LogInput[] = [];
    const log = new Logger({ send: (r) => sent.push(r) });
    const spanContext = {
      traceId: "4bf92f3577b34da6a3ce929d0e0e4736",
      spanId: "00f067aa0ba902b7",
      traceFlags: 1,
    };
    context.with(trace.setSpan(context.active(), trace.wrapSpanContext(spanContext)), () => {
      log.info("inside");
    });
    const invalid = { traceId: "0".repeat(32), spanId: "0".repeat(16), traceFlags: 0 };
    context.with(trace.setSpan(context.active(), trace.wrapSpanContext(invalid)), () => {
      log.info("invalid");
    });
    log.info("outside");
    expect(sent[0]).toMatchObject({ message: "inside", ...spanContext });
    expect(sent[1]?.traceId).toBeUndefined();
    expect(sent[2]?.traceId).toBeUndefined();
  });
});
